def admit_campaign_setup_program(source, legacy_declaration):
    tree = ast.parse(source)
    if ast.dump(tree, include_attributes=False) != EXPECTED_MODULE_AST:
        raise ValueError('campaign setup differs from its exact complete admitted module AST')
    program = copy.deepcopy(next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == 'campaign_setup_program'))
    program.body = program.body[2:]
    program.name = 'initialize_post_duel_campaign_fields'
    program.returns = ast.parse('def f() -> FirstDeploymentFrame: pass').body[0].returns
    changed = 0
    for node in ast.walk(program):
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.YieldFrom):
            call = node.value.value
            if (not isinstance(call, ast.Call) or not isinstance(call.func, ast.Name)
                    or call.func.id != '_campaign_setup_menu_call_steps'
                    or [ast.literal_eval(arg) for arg in call.args[2:]] != [198064, 1320]):
                raise ValueError('unexpected cooperative campaign call')
            call.func.id = '_campaign_call_fields'
            node.value = call
            changed += 1
    original = ast.parse('def initialize_post_duel_campaign_fields(' + legacy_declaration['signature'] + ') -> ' + legacy_declaration['returns'] + ':\n' + '\n'.join('    ' + line for line in legacy_declaration['flow'].splitlines())).body[0]
    if changed != 1 or ast.dump(program, include_attributes=False) != ast.dump(original, include_attributes=False):
        raise ValueError('campaign program does not reverse to the complete original owner')
    return dict(whole_original_owner=1300, child_call=198064, child_return=1320,
        complete_module_AST=True, original_algorithm_restored=True,
        machine_lowerer_changed=False, new_formal_bytes=0)
